const html = $json.body || '';

// 1) Quick status check
const hasNoOffers = /Keine\s+Angebote/i.test(html);

// 2) Try to extract offer/exposé links (when offers exist)
//    We filter for links that look like an offer/exposé page.
//    If the site changes markup, this still often works.
const hrefRegex = /href\s*=\s*"([^"]+)"/gi;
const found = new Set();
let m;
while ((m = hrefRegex.exec(html)) !== null) {
  let href = m[1];
  // Normalize relative URLs
  if (href.startsWith('/')) href = 'https://www.stwdo.de' + href;

  // Filter: keep only URLs that look like an offer/exposé
  // (contains 'expos' or 'angebot' and is on stwdo.de)
  if (
    href.includes('stwdo.de') &&
    /expos|angebot/i.test(href) &&
    !/aktuelle-wohnangebote/i.test(href)
  ) {
    found.add(href);
  }
}

const offers = Array.from(found).sort();

// 3) Use workflow static data to remember previous offers
const data = this.getWorkflowStaticData('global');
const prevOffers = Array.isArray(data.prevOffers) ? data.prevOffers : [];

// If no offers section exists but page is NOT "Keine Angebote",
// we still want to notify you to manually check.
const pageShowsOffers = !hasNoOffers;

const newOffers = offers.filter(u => !prevOffers.includes(u));

let notify = false;
let message = '';

if (pageShowsOffers) {
  if (offers.length > 0) {
    // Offers detected with URLs
    if (newOffers.length > 0 || prevOffers.length === 0) {
      notify = true;
      message = `🏠 *StwDo dorm offers detected!*\n\nNew offers (${newOffers.length}):\n- ${newOffers.join('\n- ')}\n\nAll extracted offers (${offers.length}):\n- ${offers.join('\n- ')}\n\nMain page: https://www.stwdo.de/wohnen/aktuelle-wohnangebote`;
    }
  } else {
    // Offers likely exist but we couldn't confidently extract URLs
    // Notify once per state-change
    const prevFlag = !!data.prevFlagOffersLikely;
    if (!prevFlag) {
      notify = true;
      message = `🏠 *StwDo page no longer says “Keine Angebote”*\n\nI couldn't extract offer links reliably (site markup may have changed), but it looks like offers may be available.\n\nPlease check: https://www.stwdo.de/wohnen/aktuelle-wohnangebote`;
    }
    data.prevFlagOffersLikely = true;
  }
} else {
  // No offers
  data.prevFlagOffersLikely = false;
}

// 4) Update stored offers only when we extracted something
if (offers.length > 0) {
  data.prevOffers = offers;
}

return [{
  json: {
    hasNoOffers,
    pageShowsOffers,
    offersCount: offers.length,
    newOffersCount: newOffers.length,
    newOffers,
    offers,
    notify,
    message
  }
}];
